import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.CrXGS008.js";const p=JSON.parse('{"title":"Custom framework","description":"","frontmatter":{},"headers":[],"relativePath":"bridge/custom.md","filePath":"bridge/custom.md"}'),s={name:"bridge/custom.md"};function i(n,e,d,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="custom-framework" tabindex="-1">Custom framework <a class="header-anchor" href="#custom-framework" aria-label="Permalink to &quot;Custom framework&quot;">​</a></h1><p>Running a framework the bridge does not support, or a heavily modified one? Plug it in yourself: every Nayretis script will use it.</p><p>The file <code>nay_lib/bridge/custom.lua</code> is shipped readable, outside the Cfx escrow. It holds two tables, one for the server and one for the client, with every function the scripts need: reading the player and their job, money, items, notifications. Each function is documented in the file with its arguments and the values it must return.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><ol><li><p>Open <code>nay_lib/bridge/custom.lua</code> and implement every function of the server and client tables with your framework&#39;s exports or events.</p></li><li><p>In <code>server.cfg</code>, force the custom adapter:</p><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>setr nay:framework &quot;custom&quot;</span></span></code></pre></div></li><li><p>Restart the server. The file is read by every resource that uses <code>nay_lib</code>, so restart them all after any change.</p></li></ol><p>The console confirms it on start: <code>Bridge ready: framework=custom ...</code>.</p><h2 id="what-the-bridge-already-does-for-you" tabindex="-1">What the bridge already does for you <a class="header-anchor" href="#what-the-bridge-already-does-for-you" aria-label="Permalink to &quot;What the bridge already does for you&quot;">​</a></h2><p>You only have to talk to your framework. The bridge itself:</p><ul><li>validates amounts and accounts (<code>cash</code> and <code>bank</code>, whole positive amounts);</li><li>checks the balance before removing money and the count before removing items;</li><li>tells the scripts when a player disconnects.</li></ul><p>Need a hand? Open a post in <code>#support</code> on the <a href="https://discord.gg/HqNyFsDBmw" target="_blank" rel="noreferrer">Nayretis Discord</a>.</p>',10)])])}const m=t(s,[["render",i]]);export{p as __pageData,m as default};
